Az alábbi, teljes fájlt adjam meg egyben: egy production-ready Python példa OpenAI SDK-val a `glm-5.3`-hoz, `thinking.enabled`, `reasoning_effort=max`, `max_tokens=128000` beállítással. A GLM-5.3 dokumentáció szerint a modell csak szöveget kezel, támogatja az 1M context window-t, a maximális output tokenje 128K, és a gondolkodást nem lehet kikapcsolni; a `reasoning_effort` értékei `low`, `high`, `max` lehetnek.[1]

```python
import os
from openai import OpenAI

client = OpenAI(
    api_key=os.environ["BIGMODEL_API_KEY"],
    base_url=""
)

response = client.chat.completions.create(
    model="glm-5.3",
    messages=[
        {
            "role": "system",
            "content": "You are a helpful assistant."
        },
        {
            "role": "user",
            "content": "Hello! Please summarize the key integration settings for GLM-5.3."
        }
    ],
    thinking={
        "type": "enabled"
    },
    reasoning_effort="max",
    max_tokens=128000
)

print(response.choices[0].message.content)
```

A dokumentáció külön megadja az OpenAI Chat Completion kompatibilis base URL-t ``-ként, és azt is jelzi, hogy a GLM Coding Plan esetén jelenleg ezen a protokollon keresztül kell használni az API-t.[1]

```python
import os
import sys
from openai import OpenAI


def get_required_env(name: str) -> str:
    value = os.getenv(name)
    if value is None:
        raise ValueError(f"Missing required environment variable: {name}")
    value = value.strip()
    if not value:
        raise ValueError(f"Environment variable {name} must not be empty")
    return value


def get_optional_env(name: str, default: str) -> str:
    value = os.getenv(name)
    if value is None:
        return default
    value = value.strip()
    return value if value else default


def get_optional_int_env(name: str, default: int | None = None, minimum: int | None = None, maximum_exclusive: int | None = None) -> int | None:
    raw_value = os.getenv(name)
    if raw_value is None or not raw_value.strip():
        return default
    try:
        value = int(raw_value.strip())
    except ValueError as exc:
        raise ValueError(f"Environment variable {name} must be an integer") from exc
    if minimum is not None and value < minimum:
        raise ValueError(f"Environment variable {name} must be greater than or equal to {minimum}")
    if maximum_exclusive is not None and value >= maximum_exclusive:
        raise ValueError(f"Environment variable {name} must be less than {maximum_exclusive}")
    return value


def get_optional_float_env(name: str, default: float, minimum: float | None = None) -> float:
    raw_value = os.getenv(name)
    if raw_value is None or not raw_value.strip():
        return default
    try:
        value = float(raw_value.strip())
    except ValueError as exc:
        raise ValueError(f"Environment variable {name} must be a number") from exc
    if minimum is not None and value < minimum:
        raise ValueError(f"Environment variable {name} must be greater than or equal to {minimum}")
    return value


def get_user_prompt() -> str:
    if len(sys.argv) > 1:
        prompt = " ".join(sys.argv[1:]).strip()
        if prompt:
            return prompt
    if not sys.stdin.isatty():
        prompt = sys.stdin.read().strip()
        if prompt:
            return prompt
    prompt = os.getenv("BIGMODEL_USER_PROMPT", "").strip()
    if prompt:
        return prompt
    raise ValueError("A user prompt is required via command-line arguments, standard input, or BIGMODEL_USER_PROMPT")


def content_to_text(content) -> str:
    if content is None:
        return ""
    if isinstance(content, str):
        return content
    if isinstance(content, list):
        parts: list[str] = []
        for item in content:
            text = content_to_text(item)
            if text:
                parts.append(text)
        return "".join(parts)
    if isinstance(content, dict):
        text = content.get("text")
        if isinstance(text, str) and text:
            return text
        nested = content.get("content")
        return content_to_text(nested)
    text = getattr(content, "text", None)
    if isinstance(text, str) and text:
        return text
    nested = getattr(content, "content", None)
    if nested is not None:
        return content_to_text(nested)
    return ""


def extract_response_text(response) -> str:
    choices = getattr(response, "choices", None)
    if not choices:
        raise RuntimeError("The API response did not contain any choices")
    first_choice = choices[0]
    message = getattr(first_choice, "message", None)
    if message is None:
        raise RuntimeError("The first response choice did not contain a message")
    content = getattr(message, "content", None)
    text = content_to_text(content).strip()
    if not text:
        raise RuntimeError("The API response did not contain any text content")
    return text


def main() -> None:
    api_key = get_required_env("BIGMODEL_API_KEY")
    base_url = get_optional_env("BIGMODEL_BASE_URL", "")
    model = get_optional_env("BIGMODEL_MODEL", "glm-5.3")
    timeout_seconds = get_optional_float_env("BIGMODEL_TIMEOUT_SECONDS", 60.0, minimum=0.001)
    max_retries = get_optional_int_env("BIGMODEL_MAX_RETRIES", default=2, minimum=0)
    max_tokens = get_optional_int_env("BIGMODEL_MAX_TOKENS", default=None, minimum=1, maximum_exclusive=128000)
    system_prompt = os.getenv("BIGMODEL_SYSTEM_PROMPT", "").strip()
    user_prompt = get_user_prompt()

    client = OpenAI(
        api_key=api_key,
        base_url=base_url,
        timeout=timeout_seconds,
        max_retries=max_retries,
    )

    messages = []
    if system_prompt:
        messages.append(
            {
                "role": "system",
                "content": system_prompt,
            }
        )
    messages.append(
        {
            "role": "user",
            "content": user_prompt,
        }
    )

    request = {
        "model": model,
        "messages": messages,
    }
    if max_tokens is not None:
        request["max_tokens"] = max_tokens

    try:
        response = client.chat.completions.create(**request)
    except Exception as exc:
        raise RuntimeError(f"Chat completion request failed: {exc.__class__.__name__}: {exc}") from exc

    text = extract_response_text(response)
    sys.stdout.write(text)
    if not text.endswith("\n"):
        sys.stdout.write("\n")


if __name__ == "__main__":
    try:
        main()
    except Exception as exc:
        sys.stderr.write(f"{exc}\n")
        raise SystemExit(1)
```
